'use strict';
const test=require('node:test'),assert=require('node:assert/strict');
const {render,pages}=require('./port-fixture');
for(const page of pages)test('BootstrapBP '+page+' renders populated and empty Widgets',async()=>{for(const empty of [false,true]){const html=await render('bootstrap-bp-hugo-theme',page,{empty});assert.match(html,/Bootstrap-BP/);assert(!html.includes('undefined'));}});
test('BootstrapBP escapes titles, rejects active cover URLs, preserves protected body',async()=>{const html=await render('bootstrap-bp-hugo-theme','index',{hostile:true,config:{profileName:'<script>alert(1)</script>',backgroundImage:'javascript:alert(1)'}});assert(!html.includes('<img src=x onerror'));assert.match(html,/&lt;img/);assert(!html.includes('src="javascript:'));assert.match(await render('bootstrap-bp-hugo-theme','post',{protected:true}),/protectPassword/);});
test('BootstrapBP delegates comments and keeps search filters in pagination',async()=>{assert(!(await render('bootstrap-bp-hugo-theme','post',{comments:false})).includes('id="comments"'));const html=await render('bootstrap-bp-hugo-theme','search',{request:'/search.html?keyword=a%26b'});assert.match(html,/keyword=a%26b&amp;page=2/);});

test('bootstrap-bp-hugo-theme renders attachment media and rejects active file URLs',async()=>{const {context}=require('./port-fixture');const {Eta}=require('eta');const path=require('node:path');for(const [mime,element] of [['image/png','img'],['audio/mpeg','audio'],['video/mp4','video'],['application/pdf',null]]){const ctx=context('bootstrap-bp-hugo-theme','attachment');const archive=await ctx.widget('Widget_Archive');archive.stack[0].options={attachment:{mime,url:'/uploads/file',name:'Download file'}};const html=await new Eta({views:path.join(__dirname,'../packages/bootstrap-bp-hugo-theme'),varName:'firekylin'}).renderAsync('attachment',ctx);assert.match(html,/href="\/uploads\/file" download/);if(element)assert(html.includes('<'+element+' '));}const ctx=context('bootstrap-bp-hugo-theme','attachment');(await ctx.widget('Widget_Archive')).stack[0].options={attachment:{mime:'image/png',url:'javascript:alert(1)'}};const html=await new Eta({views:path.join(__dirname,'../packages/bootstrap-bp-hugo-theme'),varName:'firekylin'}).renderAsync('attachment',ctx);assert(!html.includes('javascript:'));});

test('BootstrapBP identifies taxonomy',async()=>{for(const [kind,label] of [['cate','随笔'],['tag','生活']]){assert.match(await render('bootstrap-bp-hugo-theme','index',{kind}),new RegExp('<h1[^>]*>'+label+'</h1>')); }});

test('BootstrapBP allowlists palettes and layout',async()=>{for(const palette of ['default','blue','light','dark']){const html=await render('bootstrap-bp-hugo-theme','index',{config:{palette,layout:'single'}});assert(html.includes('palette-'+palette+'.css'));assert(html.includes('single-column'));}const html=await render('bootstrap-bp-hugo-theme','index',{config:{palette:'../../evil',layout:'<script>'}});assert(html.includes('palette-default.css'));assert(!html.includes('../../evil'));assert(!html.includes('<script>'));});
